153	/**
154	 * Update an existing repository row's branch and badge cells in-place.
155	 *
156	 * Cells are located by CSS class (`.repo-branch-cell`) and by the badge
157	 * wrapper's `data-repo-id` attribute — **not** by hardcoded cell indices —
158	 * so callers are free to add additional cells before or between the shared
159	 * cells without breaking this function.
160	 *
161	 * @param {HTMLTableRowElement} row          - The `<tr>` to update.
162	 * @param {string}              repoId       - Repository identifier (used to
163	 *                                             find the badge wrapper div).
164	 * @param {Object|null}         statusInfo   - New GitStatusInfo from the API,
165	 *                                             or `null` when no data is available.
166	 * @param {boolean}            [isStable]    - When `true`, the branch cell is
167	 *                                             rebuilt as plain text.
168	 * @param {function(HTMLElement, string, string): void} [onBranchCellClick]
169	 *                                             Wired to the branch trigger button
170	 *                                             in non-STABLE workspaces.
171	 */
172	export function updateRepoStatusCells(row, repoId, statusInfo, isStable, onBranchCellClick) {
173	    // Update branch cell — locate by class, not by index.
174	    const branchCell = row.querySelector('.repo-branch-cell');
175	    if (branchCell) {
176	        const currentBranch = (statusInfo && statusInfo.currentBranch) ? statusInfo.currentBranch : null;
177	        // Clear existing content before rebuilding (avoid innerHTML assignment).
178	        while (branchCell.firstChild) {
179	            branchCell.removeChild(branchCell.firstChild);
180	        }
181	        if (!isStable && currentBranch && onBranchCellClick) {
182	            const repoName = row.dataset.repoName || repoId;
183	            const trigger  = makeBranchTrigger(currentBranch, `Switch branch for ${repoName}`);
184	            trigger.addEventListener('click', () => onBranchCellClick(trigger, repoId, currentBranch));
185	            branchCell.appendChild(trigger);
186	        } else {
187	            branchCell.textContent = currentBranch || '—';
188	        }
189	    }
190	
191	    // Update badge wrapper — locate the <div data-repo-id="..."> inside the row.
192	    const badgeWrapper = row.querySelector(`div[data-repo-id="${CSS.escape(repoId)}"]`);
193	    if (badgeWrapper) {
194	        // Clear existing badge before replacing (avoid innerHTML assignment).
195	        while (badgeWrapper.firstChild) {
196	            badgeWrapper.removeChild(badgeWrapper.firstChild);
197	        }
198	        badgeWrapper.appendChild(createStatusBadge(statusInfo || null));
199	    }
200	}

